import { test } from 'node:test';
import assert from 'node:assert/strict';
import { codificarBase64, decodificarBase64, tamanhoEmBytes } from './solution.mjs';

test('codificarBase64 transforma o texto em base64', () => {
  assert.equal(codificarBase64('ola'), 'b2xh');
});

test('decodificarBase64 devolve o texto original (e a ida e volta preserva a mensagem)', () => {
  assert.equal(decodificarBase64('b2xh'), 'ola');
  const mensagem = 'A senha é 1234';
  assert.equal(decodificarBase64(codificarBase64(mensagem)), mensagem);
});

test('tamanhoEmBytes conta bytes utf8 (acentos ocupam 2)', () => {
  assert.equal(tamanhoEmBytes('cafe'), 4);
  assert.equal(tamanhoEmBytes('café'), 5);
  assert.equal(tamanhoEmBytes(''), 0);
});

test('codificarBase64 lança erro se o texto não for string', () => {
  assert.throws(() => codificarBase64(123), /string/);
});

solutionCode:
export function codificarBase64(texto) {
  if (typeof texto !== 'string') {
    throw new Error('texto precisa ser uma string');
  }
  return Buffer.from(texto, 'utf8').toString('base64');
}

export function decodificarBase64(codificado) {
  if (typeof codificado !== 'string') {
    throw new Error('codificado precisa ser uma string');
  }
  return Buffer.from(codificado, 'base64').toString('utf8');
}

export function tamanhoEmBytes(texto) {
  if (typeof texto !== 'string') {
    throw new Error('texto precisa ser uma string');
  }
  return Buffer.byteLength(texto, 'utf8');
}
